export function page(price) {
  return `<!doctype html>
<html lang="ru">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="description" content="Шесть завтраков из овсянки на ночь. Тестируем первый набор в Москве.">
<title>С вечера — овсянка на ночь</title>
<style>
:root{--paper:#faf4e9;--ink:#351629;--wine:#812849;--rose:#f1cad4;--line:#d9c4c9}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:17px/1.5 system-ui,sans-serif}a{color:inherit}a:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid #9c2c67;outline-offset:4px}.wrap{width:min(1240px,calc(100% - 80px));margin:auto}header{height:82px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.brand{font:700 30px Georgia,serif;text-decoration:none;letter-spacing:-.05em}.brand span{color:var(--wine)}nav{display:flex;gap:28px;align-items:center}nav a{font-size:15px;text-decoration:none;font-weight:650}nav a:last-child{border:1px solid var(--ink);border-radius:99px;padding:9px 17px}.hero{display:grid;grid-template-columns:1fr 1fr;min-height:590px;margin-top:24px;border-bottom:1px solid var(--line)}.intro{padding:53px 40px 50px 0;align-self:center}.eyebrow{font-size:14px;font-weight:800;color:var(--wine);text-transform:uppercase;letter-spacing:.1em}h1,h2,h3,p,figure{margin:0}h1,h2{font-family:Georgia,'Times New Roman',serif;font-weight:500;letter-spacing:-.065em;line-height:.98}h1{font-size:clamp(60px,7.4vw,117px);margin:21px 0 24px}h1 em{color:var(--wine);font-weight:500}h2{font-size:clamp(44px,5.5vw,77px);margin:11px 0 26px}.lead{font-size:clamp(17px,2vw,22px);max-width:420px}.action,button{display:inline-flex;justify-content:center;align-items:center;background:var(--ink);border:0;color:#fff2e3;border-radius:99px;padding:14px 23px;font:700 16px/1.4 system-ui;text-decoration:none;cursor:pointer}.action:hover,button:hover{background:var(--wine)}.intro .action{margin:28px 0 11px}.fine{font-size:14px;color:#6b4458}.photo{overflow:hidden;min-height:450px;background:radial-gradient(circle at 51% 43%,#fff5df 0 22%,#a8586e 23% 30%,#b86480 31% 47%,#cb8096 48%);position:relative}.photo img{display:block;width:100%;height:100%;position:absolute;object-fit:cover;object-position:center 53%}.photo figcaption{position:absolute;right:13px;bottom:12px;padding:4px 9px;background:#faf4e9;color:#542138;font-size:13px;border-radius:20px}.section{padding:68px 0}.steps{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid var(--line);gap:22px}.steps div{padding-top:19px}.steps strong{font:500 29px Georgia,serif;display:block;margin-bottom:6px}.steps p{max-width:260px}.tastes{background:#edd3da;padding:60px 0}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.taste{min-height:166px;padding:24px;display:flex;flex-direction:column;justify-content:space-between;color:#321624}.taste span{font-size:15px;font-weight:700}.taste h3{font:500 clamp(25px,3vw,38px)/1.05 Georgia,serif;letter-spacing:-.04em}.apple{background:#eed398}.berry{background:#e6a4ba}.cocoa{background:#543044;color:#fff1e6}.survey{display:grid;grid-template-columns:1fr 1.15fr;gap:50px}.survey .lead{max-width:390px}.price{font-weight:750;margin-top:18px}.form{padding:28px;background:#f4e4e4;border:1px solid #e5ccd5}.form fieldset{border:0;padding:0;margin:0 0 22px;min-width:0}.form legend{font-weight:800;padding:0;margin-bottom:9px}.option{display:flex;align-items:center;gap:10px;padding:8px 10px;border:1px solid transparent;border-radius:8px;cursor:pointer}.option:hover,.option:has(input:checked){background:#fff6ed;border-color:#ddbdc8}.option input{accent-color:var(--wine);width:19px;height:19px;flex:none;margin:0}.form button{width:100%}.form button:disabled{opacity:.65;cursor:wait}.form .fine{margin-top:11px}.status:empty{display:none}.status{margin-top:10px}.thanks{padding:22px 0}.thanks h3{font:500 34px Georgia,serif}.thanks p{margin-top:8px}footer{border-top:1px solid var(--line);padding:20px 0 35px;display:flex;align-items:center;justify-content:space-between;gap:12px}noscript{display:block;color:var(--wine);margin-top:10px}
@media(max-width:820px){.wrap{width:calc(100% - 36px)}.hero{min-height:0}.intro{padding:28px 18px 30px 0}.photo{min-height:360px}.survey{gap:23px}.section{padding:46px 0}}@media(max-width:600px){header{height:64px}nav a:first-child{display:none}.hero,.survey{grid-template-columns:1fr}.hero{margin-top:12px}.intro{padding:23px 0 27px}.photo{min-height:370px}.lead{max-width:350px}.steps,.cards{grid-template-columns:1fr}.steps{gap:15px}.steps div{padding-top:12px}.steps p{max-width:none}.taste{min-height:112px}.tastes{padding:40px 0}.form{padding:18px}footer{align-items:flex-start}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
</style>
</head>
<body>
<header class="wrap"><a class="brand" href="/">с вечера<span>.</span></a><nav aria-label="Навигация"><a href="#flavours">Вкусы</a><a href="#pilot">Первый набор</a></nav></header>
<main>
<section class="hero wrap">
<div class="intro"><p class="eyebrow">Тестируем запуск в Москве</p><h1>Завтрак<br>готовится<br><em>пока ты спишь.</em></h1><p class="lead">Овсянка с протеином на ночь. Добавь молоко вечером и достань готовый завтрак из холодильника утром.</p><a class="action" href="#pilot">Хочу попробовать</a><p class="fine">6 порций · 3 вкуса · тестовая цена ${price} ₽</p></div>
<figure class="photo"><img src="data:image/jpeg;base64," alt="Овсянка на ночь с малиной в стеклянной банке" fetchpriority="high"><figcaption>Иллюстрация продукта</figcaption></figure>
</section>
<section class="section wrap" aria-labelledby="prep-title"><h2 id="prep-title">Вечером минута.<br>Утром завтрак.</h2><div class="steps"><div><strong>Добавь молоко</strong><p>Высыпь один пакетик в банку, влей молоко или растительный напиток и перемешай.</p></div><div><strong>Оставь на ночь</strong><p>Поставь банку в холодильник. За ночь хлопья станут мягкими.</p></div><div><strong>Завтракай</strong><p>Ешь холодной дома или возьми с собой.</p></div></div></section>
<section id="flavours" class="tastes"><div class="wrap"><p class="eyebrow">Дегустационный набор</p><h2>Три вкуса на неделю</h2><div class="cards"><article class="taste apple"><span>2 порции</span><h3>Яблоко и корица</h3></article><article class="taste berry"><span>2 порции</span><h3>Малина и ваниль</h3></article><article class="taste cocoa"><span>2 порции</span><h3>Какао и банан</h3></article></div><p class="fine" style="margin-top:16px">Цель для рецептуры — около 20 г белка в сухой порции.</p></div></section>
<section id="pilot" class="section wrap survey">
<div><p class="eyebrow">Первый набор</p><h2>Попробовали бы?</h2><p class="lead">Хотим понять, стоит ли запускать доставку по Москве. Расскажите, готовы ли вы купить такой набор.</p><p class="price">6 завтраков за ${price} ₽ · 165 ₽ за порцию</p></div>
<form class="form" id="survey">
<div id="fields">
<fieldset><legend>Купили бы набор за ${price} ₽ с доставкой по Москве?</legend>
<label class="option"><input type="radio" name="intent" value="yes" required>Да, по этой цене</label>
<label class="option"><input type="radio" name="intent" value="cheaper">Да, если будет дешевле</label>
<label class="option"><input type="radio" name="intent" value="no">Нет</label>
</fieldset>
<fieldset><legend>Какой формат интереснее?</legend>
<label class="option"><input type="radio" name="format" value="once" required>Разово попробовать</label>
<label class="option"><input type="radio" name="format" value="regular">Получать набор регулярно</label>
<label class="option"><input type="radio" name="format" value="unsure">Пока не знаю</label>
</fieldset>
<button type="submit">Отправить ответ</button><p class="fine">Анонимный опрос. Оплаты и заказа нет.</p>
</div>
<div class="status" id="status" aria-live="polite"></div><noscript>Для отправки ответа включите JavaScript.</noscript>
</form></section>
</main><footer class="wrap"><a class="brand" href="/">с вечера<span>.</span></a><span class="fine">Проект завтраков из овсянки · Москва</span></footer>
<script>
const form = document.getElementById('survey');
const fields = document.getElementById('fields');
const status = document.getElementById('status');
const key = 's-vechera-visitor-v1';
function read(key) { try { return localStorage.getItem(key); } catch { return null; } }
function save(key, value) { try { localStorage.setItem(key, value); } catch {} }
const id = read(key) || crypto.randomUUID();
save(key, id);
const source = new URLSearchParams(location.search).get('utm_source') || 'direct';
const answeredKey = 's-vechera-answered-v1';
async function send(path, payload) {
  const response = await fetch(path, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({id, source, ...payload}) });
  if (!response.ok) throw new Error('Request failed');
}
function thank() {
  fields.hidden = true;
  status.innerHTML = '<div class="thanks"><h3>Спасибо за ответ!</h3><p>Вы помогли решить, стоит ли запускать первый набор в Москве.</p></div>';
}
if (read(answeredKey) === 'yes') thank();
send('/api/visit', {}).catch(() => {});
form.addEventListener('submit', async event => {
  event.preventDefault();
  const button = form.querySelector('button');
  button.disabled = true;
  status.textContent = 'Отправляем ответ…';
  const values = new FormData(form);
  try {
    await send('/api/response', { intent: values.get('intent'), format: values.get('format'), price: ${price} });
    save(answeredKey, 'yes');
    thank();
  } catch {
    status.textContent = 'Ответ пока не сохранился. Попробуйте ещё раз.';
    button.disabled = false;
  }
});
</script></body></html>`;
}
